/**
 * What went wrong. A kind added later reads as `Unknown`.
 */
public
enum WseError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case Config(reason: String
    )
    case Connect(reason: String
    )
    case Auth(reason: String
    )
    case Timeout(reason: String
    )
    case Encryption(reason: String
    )
    case Signing(reason: String
    )
    case GaveUp(reason: String
    )
    case NotConnected
    case Full
    case Closed
    case Encode(reason: String
    )
    case Decode(reason: String
    )
    case Cancelled
    case Busy
    case Internal(reason: String
    )
    case Unknown(reason: String
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

