public struct FfiConverterTypeWseError: FfiConverterRustBuffer {
    typealias SwiftType = WseError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WseError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .Config(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Connect(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Auth(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Timeout(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Encryption(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Signing(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .GaveUp(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .NotConnected
        case 9: return .Full
        case 10: return .Closed
        case 11: return .Encode(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Decode(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 13: return .Cancelled
        case 14: return .Busy
        case 15: return .Internal(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 16: return .Unknown(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WseError, into buf: inout [UInt8]) {
        switch value {





