/**
 * One thing the client heard, in order.
 */

public enum WseItem: Equatable, Hashable {

    case message(message: WseMessage
    )
    case binary(bytes: Data
    )
    case connected(connectionId: String, userId: String?, reconnected: Bool, recovery: Bool
    )
    case disconnected(code: UInt16?, reason: String, retryInMs: UInt64, attempt: UInt32
    )
    /**
     * Paused by the application: no connection until the last reason is
     * cleared; topics and positions stay.
     */
    case paused(reasons: [String]
    )
    case subscribed(topics: [String], failed: [String], recovery: [WseTopicRecovery]
    )
    /**
     * Messages of a topic that will not come: reload what depends on them.
     */
    case gap(topic: String, epoch: UInt32, first: UInt64?, last: UInt64?, reason: String
    )
    case serverError(code: String, text: String, detailsJson: String
    )
    /**
     * The client stopped for good; `reason` when it was not closed by the application.
     */
    case closed(reason: String?
    )
    /**
     * recover-or-resync: bring the state of `topics` up to date (the
     * reason of each, what the consumer committed), then call
     * `resynced(round)`; their messages wait till then.
     */
    case resync(round: UInt64, topics: [String], reasons: [String], committed: [WseStreamPosition]
    )
    /**
     * A topic's continuity changed, and why it is not continuous.
     */
    case continuity(topic: String, continuity: WseContinuity, reason: String?
    )
    /**
     * The saved checkpoint is not this client's: its realm, user,
     * consumer, schema or version, or it is malformed.
     */
    case checkpointRejected(reason: String
    )
    /**
     * Something this version does not know.
     */
    case unknown(name: String
    )





}

#if compiler(>=6)
extension WseItem: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWseItem: FfiConverterRustBuffer {
    typealias SwiftType = WseItem

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WseItem {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .message(message: try FfiConverterTypeWseMessage.read(from: &buf)
        )

        case 2: return .binary(bytes: try FfiConverterData.read(from: &buf)
        )

        case 3: return .connected(connectionId: try FfiConverterString.read(from: &buf), userId: try FfiConverterOptionString.read(from: &buf), reconnected: try FfiConverterBool.read(from: &buf), recovery: try FfiConverterBool.read(from: &buf)
        )

        case 4: return .disconnected(code: try FfiConverterOptionUInt16.read(from: &buf), reason: try FfiConverterString.read(from: &buf), retryInMs: try FfiConverterUInt64.read(from: &buf), attempt: try FfiConverterUInt32.read(from: &buf)
        )

        case 5: return .paused(reasons: try FfiConverterSequenceString.read(from: &buf)
        )

        case 6: return .subscribed(topics: try FfiConverterSequenceString.read(from: &buf), failed: try FfiConverterSequenceString.read(from: &buf), recovery: try FfiConverterSequenceTypeWseTopicRecovery.read(from: &buf)
        )

        case 7: return .gap(topic: try FfiConverterString.read(from: &buf), epoch: try FfiConverterUInt32.read(from: &buf), first: try FfiConverterOptionUInt64.read(from: &buf), last: try FfiConverterOptionUInt64.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )

        case 8: return .serverError(code: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf), detailsJson: try FfiConverterString.read(from: &buf)
        )

        case 9: return .closed(reason: try FfiConverterOptionString.read(from: &buf)
        )

        case 10: return .resync(round: try FfiConverterUInt64.read(from: &buf), topics: try FfiConverterSequenceString.read(from: &buf), reasons: try FfiConverterSequenceString.read(from: &buf), committed: try FfiConverterSequenceTypeWseStreamPosition.read(from: &buf)
        )

        case 11: return .continuity(topic: try FfiConverterString.read(from: &buf), continuity: try FfiConverterTypeWseContinuity.read(from: &buf), reason: try FfiConverterOptionString.read(from: &buf)
        )

        case 12: return .checkpointRejected(reason: try FfiConverterString.read(from: &buf)
        )

        case 13: return .unknown(name: try FfiConverterString.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WseItem, into buf: inout [UInt8]) {
        switch value {


        case let .message(message):
            writeInt(&buf, Int32(1))
            FfiConverterTypeWseMessage.write(message, into: &buf)


        case let .binary(bytes):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(bytes, into: &buf)


        case let .connected(connectionId,userId,reconnected,recovery):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(connectionId, into: &buf)
            FfiConverterOptionString.write(userId, into: &buf)
            FfiConverterBool.write(reconnected, into: &buf)
            FfiConverterBool.write(recovery, into: &buf)


        case let .disconnected(code,reason,retryInMs,attempt):
            writeInt(&buf, Int32(4))
            FfiConverterOptionUInt16.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterUInt64.write(retryInMs, into: &buf)
            FfiConverterUInt32.write(attempt, into: &buf)


        case let .paused(reasons):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceString.write(reasons, into: &buf)


        case let .subscribed(topics,failed,recovery):
            writeInt(&buf, Int32(6))
            FfiConverterSequenceString.write(topics, into: &buf)
            FfiConverterSequenceString.write(failed, into: &buf)
            FfiConverterSequenceTypeWseTopicRecovery.write(recovery, into: &buf)


        case let .gap(topic,epoch,first,last,reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(topic, into: &buf)
            FfiConverterUInt32.write(epoch, into: &buf)
            FfiConverterOptionUInt64.write(first, into: &buf)
            FfiConverterOptionUInt64.write(last, into: &buf)
            FfiConverterString.write(reason, into: &buf)


        case let .serverError(code,text,detailsJson):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterString.write(detailsJson, into: &buf)


        case let .closed(reason):
            writeInt(&buf, Int32(9))
            FfiConverterOptionString.write(reason, into: &buf)


        case let .resync(round,topics,reasons,committed):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(round, into: &buf)
            FfiConverterSequenceString.write(topics, into: &buf)
            FfiConverterSequenceString.write(reasons, into: &buf)
            FfiConverterSequenceTypeWseStreamPosition.write(committed, into: &buf)


        case let .continuity(topic,continuity,reason):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(topic, into: &buf)
            FfiConverterTypeWseContinuity.write(continuity, into: &buf)
            FfiConverterOptionString.write(reason, into: &buf)


        case let .checkpointRejected(reason):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(reason, into: &buf)


        case let .unknown(name):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(name, into: &buf)

        }
    }
}


